#!/usr/bin/env python
"""Regenerate the compiled schema snapshot in ``docs/references/compiled-schema.yaml``.

Usage::

    make compiled_schema
"""

import os

import django
import yaml

HEADER = """\
# Compiled authorization schema of the built-in applets, generated by `make compiled_schema`.
# Each role lists its permissions grouped by the applet that adds them.
"""


def main():
    """Compile the built-in schema and write it to the snapshot file."""
    os.environ.setdefault("DJANGO_SETTINGS_MODULE", "openedx_authz.settings.test")
    django.setup()

    # These modules read Django settings on import, so they load after setup.
    from openedx_authz.engine.schema.pipeline import SchemaPipeline
    from openedx_authz.tests.applets.test_builtin_definitions import COMPILED_SCHEMA_SNAPSHOT, snapshot_data

    data = snapshot_data(SchemaPipeline().compile())
    content = yaml.safe_dump(data, sort_keys=False, allow_unicode=True, width=1000)
    COMPILED_SCHEMA_SNAPSHOT.write_text(HEADER + content, encoding="utf-8")


if __name__ == "__main__":
    main()
